import { Meta, StoryObj } from "@storybook/react";
import DigitalRideMediaQrCodeConnectBlock from "./digital-ride-media-qr-code-connect-block";
import { action } from "storybook/actions";
import { expect } from "storybook/test";
import {
  WithMockedDate,
  WithResetQueryCache,
  withMockedDate,
  withQueryProvider,
  withResetQueryCache,
} from "../../../../../.storybook/preview";
import { LocalStorageHelper, throwError } from "@/core/helpers";
import {
  MOCKED_DATE,
  allMedia,
  delay,
  waitForVisibleElement,
  elementIsNotInDocument,
  fetchAlbumMock,
  getMediaOnQrCodeAccountMock,
  withFocusedMediaModalMinHeight,
} from "../digital-ride-media-storybook-helpers";
import { ComponentProps } from "react";
import { QueryProvider } from "@/core/providers";
import { SingleMediaResponse } from "@parksandresorts/webapiproxy-types";
import DigitalRideMediaSearchBlock from "../search-block/digital-ride-media-search-block";

type StoryArgs = ComponentProps<WithResetQueryCache<WithMockedDate<typeof DigitalRideMediaQrCodeConnectBlock>>> & {
  imageHash?: string;
};

const meta: Meta<StoryArgs> = {
  title: "Modules/Digital Ride Media/QR Code Connect Block",
  component: DigitalRideMediaQrCodeConnectBlock,
  argTypes: {
    mockedDate: {
      control: {
        type: "date",
      },
    },
  },
  decorators: [withResetQueryCache, withMockedDate, withQueryProvider, withFocusedMediaModalMinHeight],
  parameters: {
    chromatic: { delay: 4000 },
  },
  render: function StoryComponent({ ...args }) {
    LocalStorageHelper.setItem("savedRideMediaAlbumIds", [], undefined);
    if (args.imageHash) {
      window.location.hash = args.imageHash;
    }
    return (
      <QueryProvider>
        <div style={{ background: "var(--foundation-color-primary-200)" }}>
          <i>
            <b>Information about story:</b>
            <br />
            See `Save To Album` stories to view all options/versions for saving media to an album
          </i>
        </div>
        {!args.imageHash ? (
          <DigitalRideMediaQrCodeConnectBlock
            {...args}
            navigateToAlbum={action("navigateToAlbum")}
            service={{
              getMediaOnQrCodeAccount: async (_accountId) => {
                await delay(1000);
                return getMediaOnQrCodeAccountMock();
              },
              fetchAlbum: fetchAlbumMock,
              // Functions not needed for the stories
              connectQrCodeToAlbum: () => throwError("Not implemented"),
              createNewAlbum: () => throwError("Not implemented"),
              fetchAlbumMedia: () => throwError("Not implemented"),
              searchForMedia: () => throwError("Not implemented"),
              createNewAlbumWithInitialMedia: () => throwError("Not implemented"),
              addMediaToAlbum: () => throwError("Not implemented"),
              updateName: () => throwError("Not implemented"),
              deleteMediaFromAlbum: () => throwError("Not implemented"),
              deleteAlbum: () => throwError("Not implemented"),
              addContactInformationToAlbum: () => throwError("Not implemented"),
            }}
          />
        ) : (
          <DigitalRideMediaSearchBlock
            {...args}
            rides={[
              { pomvomCode: "ride-1", rideName: "Ride 1" },
              { pomvomCode: "ride-2", rideName: "Ride 2" },
            ]}
            pomvomCodeToRideIdConverterConfig={[
              { rideId: 123, pomvomCode: "ride-1" },
              { rideId: 456, pomvomCode: "ride-2" },
            ]}
            navigateToStartPage={() => {
              action("navigateToStartPage")();
            }}
            service={{
              searchForMedia: async (rideId, prefix, number) => {
                action("searchForMedia")(rideId, prefix, number);
                await delay(1000);
                const matchedMedia = Object.values(allMedia).find((media) => media.mediaId === `${prefix}-${number}`);
                if (!matchedMedia) {
                  throw new Error(`No media found for ${prefix}-${number}`);
                }
                return { item: matchedMedia } as SingleMediaResponse;
              },
              // Functions not needed for the stories
              createNewAlbumWithInitialMedia: () => throwError("Not implemented"),
              fetchAlbum: () => throwError("Not implemented"),
              addMediaToAlbum: () => throwError("Not implemented"),
              addContactInformationToAlbum: () => throwError("Not implemented"),
              fetchAlbumMedia: () => throwError("Not implemented"),
              updateName: () => throwError("Not implemented"),
              deleteMediaFromAlbum: () => throwError("Not implemented"),
              deleteAlbum: () => throwError("Not implemented"),
              createNewAlbum: () => throwError("Not implemented"),
              getMediaOnQrCodeAccount: () => throwError("Not implemented"),
              connectQrCodeToAlbum: () => throwError("Not implemented"),
            }}
          />
        )}
      </QueryProvider>
    );
  },
};

export default meta;

type Story = StoryObj<typeof meta>;

/** Mocks scanning a QR code linked to media.
 * Media is found and only other saving options are shown. */
export const FoundMedia: Story = {
  args: {
    mockedDate: new Date(MOCKED_DATE),
    qrCodeAccountId: "12345678",
  },
  play: async ({ canvasElement }) => {
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-qr-code-connect-heading",
      assert: (el) => expect(el).toHaveTextContent("1"),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-save-to-album-other-saving-options",
    });
    await elementIsNotInDocument({
      canvasElement,
      testIds: ["digital-ride-media-existing-albums-list"],
    });
  },
};

/** Mocks scanning a QR code linked to media that is too old.
 * Search block with error banner and prefilled values are therefore shown. */
export const FindMediaError: Story = {
  args: {
    ...FoundMedia.args,
    imageHash: "rideId=ride-1&imageNumberPrefix=Q&imageNumber=1001",
  },
  play: async ({ canvasElement }) => {
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-card-ride-select",
      assert: (el) => expect(el).toHaveAttribute("data-has-error", "false"),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-card-image-prefix",
      assert: (el) => expect(el).toHaveValue("Q"),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-card-image-number",
      assert: (el) => expect(el).toHaveValue("1001"),
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-search-card-error-banner",
    });
  },
};
